package dev.rise.module.impl.other;

import dev.rise.Rise;
import dev.rise.event.impl.motion.PreMotionEvent;
import dev.rise.event.impl.packet.PacketReceiveEvent;
import dev.rise.module.Module;
import dev.rise.module.api.ModuleInfo;
import dev.rise.module.enums.Category;
import dev.rise.setting.impl.ModeSetting;
import dev.rise.util.math.TimeUtil;
import dev.rise.util.player.PacketUtil;
import net.minecraft.network.play.client.C14PacketTabComplete;
import net.minecraft.network.play.server.S3APacketTabComplete;

import java.util.ArrayList;

@ModuleInfo(name = "Plugins", description = "Displays what plugins a server has in chat", category = Category.OTHER)
public final class Plugins extends Module {

    private final ModeSetting mode = new ModeSetting("Mode", this, "Normal", "Normal", "Bypass");

    private final ArrayList<String> cachedPlugins = new ArrayList<>();
    private final TimeUtil timer = new TimeUtil();

    @Override
    public void onPreMotion(final PreMotionEvent event) {
        switch (mode.getMode()) {
            case "Normal":
                if (timer.hasReached(5000L)) {
                    this.registerNotification("Failed to detect any plugins.");
                    this.toggleModule();
                }
                break;

            case "Bypass":
                if (timer.hasReached(2500L))
                    this.toggleModule();
                break;
        }
    }

    @Override
    public void onPacketReceive(final PacketReceiveEvent event) {
        if (event.getPacket() instanceof S3APacketTabComplete) {
            switch (mode.getMode()) {
                case "Normal":
                    for (final String command : ((S3APacketTabComplete) event.getPacket()).func_149630_c()) {
                        final String[] pluginCommand = command.split(":");
                        if (pluginCommand.length > 1 && !pluginCommand[0].startsWith("/minecraft")) {
                            final String plugin = pluginCommand[0].replaceAll("/", "");

                            if (!cachedPlugins.contains("Plugins:")) {
                                Rise.addChatMessage("Plugins:");
                                cachedPlugins.add("Plugins:");
                            }

                            if (!cachedPlugins.contains(plugin)) {
                                cachedPlugins.add(plugin);
                                Rise.addChatMessage(plugin);
                            }
                        }
                    }

                    if (cachedPlugins.isEmpty())
                        this.registerNotification("No plugins found.");

                    this.toggleModule();
                    break;

                case "Bypass":
                    for (final String command : ((S3APacketTabComplete) event.getPacket()).func_149630_c()) {
                        final String[] pluginCommand = command.split(":");
                        if (pluginCommand.length > 1 && !pluginCommand[0].startsWith("/minecraft")) {
                            final String plugin = pluginCommand[0].replaceAll("/", "");

                            if (!cachedPlugins.contains(plugin))
                                cachedPlugins.add(plugin);
                        }
                    }
                    break;
            }
        }
    }

    @Override
    protected void onEnable() {
        switch (mode.getMode()) {
            case "Normal":
                PacketUtil.sendPacket(new C14PacketTabComplete("/"));
                break;

            case "Bypass":
                final String alphabet = "abcdefghijklmnopqrstuvwxyz";

                for (int i = 0; i < alphabet.length(); i++)
                    PacketUtil.sendPacket(new C14PacketTabComplete("/" + alphabet.charAt(i)));
                break;
        }
        cachedPlugins.clear();
        timer.reset();
    }

    @Override
    protected void onDisable() {
        if (mode.is("Bypass") && !cachedPlugins.isEmpty()) {
            Rise.addChatMessage("Plugins:");

            for (final String name : cachedPlugins)
                Rise.addChatMessage(name);
        }
    }
}
// NOTE (AI): Plugins enumerates a server's plugin list via tab completion. Normal mode sends C14 with the string '/' and parses the S3APacketTabComplete reply. Bypass mode sends '/a' through '/z' one letter at a time; servers that strip command names from the plain '/' dump still leak them in the per-letter replies, because the completion logic filters by prefix instead of hiding the command set. The module caches results and disables itself after the sweep.

// ===== FILE: Sigma 4.11 — info/sigmaclient/management/command/impl/PluginFinder.java =====
package info.sigmaclient.management.command.impl;

import info.sigmaclient.event.Event;
import info.sigmaclient.event.impl.EventPacket;
import info.sigmaclient.util.Timer;
import info.sigmaclient.event.EventSystem;
import info.sigmaclient.event.RegisterEvent;
import info.sigmaclient.management.command.Command;
import info.sigmaclient.util.NetUtil;
import info.sigmaclient.util.misc.ChatUtil;
import net.minecraft.network.play.client.C14PacketTabComplete;
import net.minecraft.network.play.server.S3APacketTabComplete;

/**
 * Created by Arithmo on 5/7/2017 at 3:12 PM.
 */
public class PluginFinder extends Command {

    public PluginFinder(String[] names, String description) {
        super(names, description);
    }

    private Timer timer = new Timer();

    @Override
    public void fire(String[] args) {
        try {
            timer.reset();
            EventSystem.register(this);
            NetUtil.sendPacket(new C14PacketTabComplete("/"));
            ChatUtil.printChat(chatPrefix + "Listening for a S3APacketTabComplete for 20s!");
        } catch (Exception ceankoFucksOff) {
            ceankoFucksOff.printStackTrace();
        }
    }

    @RegisterEvent(events = {EventPacket.class})
    public void onEvent(Event event) {
        try {
            EventPacket ep = (EventPacket) event;
            if (ep.getPacket() instanceof S3APacketTabComplete) {
                S3APacketTabComplete packet = (S3APacketTabComplete) ep.getPacket();
                String[] commands = packet.func_149630_c();
                String message = "";
                int size = 0;

                for (String command : commands) {
                    String pluginName = command.split(":")[0].substring(1);

                    if (!message.contains(pluginName) && command.contains(":") && !pluginName.equalsIgnoreCase("minecraft") && !pluginName.equalsIgnoreCase("bukkit")) {
                        size++;
                        if (message.isEmpty()) {
                            message += pluginName;
                        } else {
                            message += "\2478, \247a" + pluginName;
                        }
                    }
                }

                if (!message.isEmpty()) {
                    ChatUtil.printChat(chatPrefix + "\2477Plugins (\247f" + size + "\2477): \247a " + message + "\2477.");
                } else {
                    ChatUtil.printChat(chatPrefix + "Plugins: none.");
                }
                EventSystem.unregister(this);
                event.setCancelled(true);
            }

            if (timer.delay(20000)) {
                EventSystem.unregister(this);
                ChatUtil.printChat(chatPrefix + "Stopped listening for an S3APacketTabComplete! Took to long (20s)!");
            }
        } catch (Exception ceankoFucksOff) {
            ceankoFucksOff.printStackTrace();
        }
    }

    @Override
    public String getUsage() {
        return "pluginfinder";
    }

}
// NOTE (AI): PluginFinder is a chat command, not a module. fire() resets a 20 second timer, registers an event listener and sends one C14 with '/'. The listener watches EventPacket for S3APacketTabComplete, splits each completion on ':' and prints the plugin prefix, skipping minecraft and bukkit. It unregisters after the first reply or the 20 second timeout.

